;(function($,window,document,undefined){var SimpleValidate=function(elem,options){this.elem=elem;this.$elem=$(elem);this.options=options;this.metadata=this.$elem.data('plugin-options');this.$requiredInputs=this.$elem.find(':input.required');};SimpleValidate.prototype={defaults:{errorClass:'error',errorText:'{label} is a required field.',emailErrorText:'Please enter a valid {label}',errorElement:'strong',removeLabelChar:'*',inputErrorClass:'input-error',completeCallback:'',ajaxRequest:false},init:function(){var self=this;self.config=$.extend({},self.defaults,self.options,self.metadata);self.errorMsgType=self.config.errorText.search(/{label}/);self.emailErrorMsgType=self.config.emailErrorText.search(/{label}/);self.$elem.on('submit.simpleValidate',$.proxy(self.handleSubmit,self));return this;},checkField:function(index){var self=this;var $field=self.$requiredInputs.eq(index);var fieldValue=$.trim($field.val());var labelText=$field.siblings('label').text().replace(self.config.removeLabelChar,'');var errorMsg='';if(fieldValue===''){errorMsg=self.formatErrorMsg(self.config.errorText,labelText,self.errorMsgType);self.hasError=true;}else if($field.hasClass('email')){if(!(/^([_a-z0-9-]+)(\.[_a-z0-9-]+)*@([a-z0-9-]+)(\.[a-z0-9-]+)*(\.[a-z]{2,4})$/.test(fieldValue.toLowerCase()))){errorMsg=self.formatErrorMsg(self.config.emailErrorText,labelText,self.emailErrorMsgType);self.hasError=true;}}
if(errorMsg!==''){$field.addClass(self.config.inputErrorClass).after('<'+self.config.errorElement+' class="'+self.config.errorClass+'">'+errorMsg+'</'+self.config.errorElement+'>');}},formatErrorMsg:function(errorText,labelText,errorMsgType){return(errorMsgType>-1)?errorText.replace('{label}',labelText):errorText;},handleSubmit:function(e){var self=this;this.hasError=false;self.$elem.find(self.config.errorElement+'.'+self.config.errorClass).remove();self.$elem.find(':input.'+self.config.inputErrorClass).removeClass(self.config.inputErrorClass);self.$requiredInputs.each($.proxy(self.checkField,self));if(self.hasError){e.preventDefault();}else if(self.config.completeCallback!==''){self.config.completeCallback(self.$elem);if(self.config.ajaxRequest){e.preventDefault();}}}};SimpleValidate.defaults=SimpleValidate.prototype.defaults;$.fn.simpleValidate=function(options){return this.each(function(){new SimpleValidate(this,options).init();});};})(jQuery,window,document);